  insert into public.brands (name, website, description, country, status) values ('MAKE UP FOR EVER', 'https://www.makeupforever.com', 'LVMH professional makeup brand (founded by makeup artists, known for HD Skin and Artist Color lines) running an Affiliate Partner Program on Rakuten Advertising: makeup artists and creators earn 20%+ commission on all sales, publishers negotiate rates with the brand''s affiliate team, and select creator partners are eligible for free samples and product.', null, 'published') returning id into bid;
