  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.makeupforever.com/us/en/affiliates.html', 'official_site', 'affiliate', 'MAKE UP FOR EVER''s own affiliates page routes sign-up through Rakuten Advertising (create a Rakuten account, request to join the program, then submit the brand''s required form; approval can take up to 2 weeks) and publishes the program highlights: ''20%+* Commission on all sales'' for makeup artists & creators (publishers agree rates directly with the affiliate team at makeupforeveraffiliateteam@assemblyglobal.com), increased rates for high performers, and free samples/product for select creator partners. The page publishes NO statement about an earnings cap or maximum, so commission_cap is recorded as unknown, never guessed.', 'verified', now());
