  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 15, 16, 12, 7, 5, '{"niche_fit": "Pro-artist makeup (complexion, color, brushes) is core beauty-UGC material with endless tutorial and review formats.", "ugc_evidence": "A structured network program explicitly recruiting makeup artists and content creators, with free product for select creator partners.", "compensation": "20%+ published for makeup artists & creators with increases for high performers \u2014 strong rate, but no no-cap statement is published, so the cap stays honestly unknown.", "contact_access": "Published affiliate-team email plus a step-by-step sign-up page on the brand''s own site.", "opportunity_availability": "Open application via Rakuten plus a required brand form; approval can take up to 2 weeks.", "credibility": "Global LVMH prestige brand sold in Sephora and professional channels worldwide."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('amika', 'https://www.loveamikapro.com', 'Salon haircare brand (shampoos, masks, styling and tools sold through salons and Sephora) running a Salon Affiliate Program on Refersion: licensed US cosmetologists get a unique ordering URL for clients and earn 20% commission on sales through it, paid bi-weekly via Trolley once $150 of product has been ordered through the URL in a six-month period.', 'United States', 'published') returning id into bid;
