  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'amika Salon Affiliate Program (Refersion)', 'https://amika.refersion.com/?oid=43923', 'https://amika.refersion.com/?oid=43923', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://amika.refersion.com/?oid=43923', 'official_site', 'affiliate', 'amika''s own Refersion program page publishes the full Salon Affiliate Program terms: enrollment requires a licensed cosmetologist located in the United States with a current valid license; on acceptance the affiliate receives a unique URL, and once $150 of amika products has been ordered through it within a six-month period, ''a commission in the amount of 20% of the amount of sales made through your URL will be paid to you on a bi-weekly basis'' (paid via a Trolley account; commission totals under $30 in any six-month period are not paid out). The terms publish NO statement about an earnings cap or maximum, so commission_cap is recorded as unknown, never guessed. The page''s contact addresses render masked in text form, so no email is recorded.', 'verified', now());
