  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 12, 16, 8, 5, 5, '{"niche_fit": "Colorful, shelf-famous haircare with strong routine and transformation content potential for stylist-creators.", "ugc_evidence": "A structured salon affiliate program with a client-ordering URL; it is a professional channel rather than an open creator program, and no creator count is published.", "compensation": "20% is a top-tier published rate, but it only starts after $150 of URL sales per six months and no cap statement is published, so the cap stays honestly unknown.", "contact_access": "Full terms and application on the brand''s Refersion page; the page''s email addresses render masked, so no public email is recorded.", "opportunity_availability": "Restricted: licensed US cosmetologists only, which excludes general UGC creators.", "credibility": "Major professional haircare brand (Amika LLC, Brooklyn NY) sold in salons and Sephora."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Allies of Skin', 'https://us.allies.shop', 'Premium clinical skincare brand (Allies of Skin — peptide, retinal and antioxidant formulas) whose own North America store runs The Allies Affiliate Programme: affiliates earn from a minimum of 15% commission, higher depending on performance, with affiliate-only offers, dedicated support and bonuses for top performers.', null, 'published') returning id into bid;
