  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'The Allies Affiliate Programme', 'https://us.allies.shop/pages/affiliates', 'https://us.allies.shop/pages/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://us.allies.shop/pages/affiliates', 'official_site', 'affiliate', 'The Allies of Skin North America store''s own affiliate page (''Become an ALLIES AFFILIATE'') publishes a ''High Commission Rate — From a minimum of 15% and higher depending on performance'', exclusive newsletter updates, affiliate-only offers, dedicated affiliate support, bonuses and incentives for top performers, and a ''Special Brand Commission Rates'' line (''Earn up to $15k+ per month''). That $15k+ figure is a marketing claim about special rates, NOT a statement that earnings are uncapped, and the page publishes no no-cap/no-maximum statement — so commission_cap is recorded as unknown, never guessed.', 'verified', now());
