  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 13, 16, 9, 7, 5, '{"niche_fit": "High-potency serums and creams with visible-results positioning are proven premium skincare-UGC material.", "ugc_evidence": "An own-store affiliate programme with dedicated support and top-performer bonuses; no hard creator count was published.", "compensation": "Minimum 15% rising with performance is a strong published floor, but no cap statement is published, so the cap stays honestly unknown.", "contact_access": "Program page on the brand''s own North America store; no public affiliate email published on the page.", "opportunity_availability": "Programme is presented as open to join from the brand''s own page.", "credibility": "Internationally distributed premium clinical brand with major beauty-retail presence."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Delux Tanners', 'https://deluxtanning.com', 'UK sunbed and self-tan brand (tanning creams and intensifiers such as Bubblegum Mania and Tropic Like It''s Hot) running an affiliate programme through Shopify Collabs: followers get 10% off with the creator''s code, affiliates earn 10% commission on every sale including repeat orders, there is no minimum follower count, and the page states there is no cap on what you can earn, with an invite-only Creator tier above it.', 'United Kingdom', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://deluxtanning.com/pages/collab', 'https://deluxtanning.com/pages/collab', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Shopify Collabs', 10, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://deluxtanning.com/pages/collab.', 'https://deluxtanning.com/pages/collab', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Delux Tanners Affiliate Programme (Shopify Collabs)', 'https://deluxtanning.com/pages/collab', 'https://deluxtanning.com/pages/collab', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://deluxtanning.com/pages/collab', 'official_site', 'affiliate', 'Delux Tanners'' own Collabs page publishes the programme in a stat strip — 10% off for followers, 10% commission on every sale, 0 minimum followers, ''No cap on what you can earn'' — and repeats in its programme summary: ''No minimum followers. No earning limits.'' Tracking and payment run through the Shopify Collabs dashboard, repeat orders from returning customers count, and regular posters who drive sales can be invited into a higher-rate Creator programme with product to try and payment when content runs as ads. The earnings cap is therefore recorded as uncapped on the brand''s own explicit statements.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://deluxtanning.com/pages/collab', 'official_site', 'ugc_collab', 'The page is built around creator content — it lists the content that works (routines, sunbed and holiday glow selfies, unboxings, honest reviews), shows named Delux creators, and offers a paid Creator tier where the brand pays when it runs creator content as an ad.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://deluxtanning.com/pages/collab', 'official_site', 'creator_saturation', 'No Beacons brand page or other hard creator count for Delux Tanners surfaced in this research, so creator saturation is recorded as unknown rather than estimated.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 15, 14, 10, 9, 3, '{"niche_fit": "Tanning routines and glow results are a defined beauty-UGC niche, though UV-tan positioning narrows the audience versus self-tan-only brands.", "ugc_evidence": "A creator-first programme page with content guidance, featured creators and a paid Creator tier on top of the affiliate rate.", "compensation": "10% on every sale including repeats, with the brand''s own page stating ''No cap'' and ''No earning limits'' \u2014 verified uncapped at a mid rate.", "contact_access": "Short application form on the brand''s own Collabs page; applications are reviewed by the brand itself.", "opportunity_availability": "Open to everyone with zero minimum followers \u2014 the lowest barrier in this round.", "credibility": "Trading UK tanning brand with a live Shopify Collabs programme; smaller and younger than the prestige names in this batch."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Luxy Hair', 'https://www.luxyhair.com', 'Clip-in human hair extensions brand running an Ambassador Program on Aspire: ambassadors share a code/link giving customers $20 off orders of $80+, earn tiered commission of 5% base, 7% after $5,000 in sales and 10% after $10,000, receive free extension sets twice a year, and commit to one original content post per month for a minimum of three months.', null, 'published') returning id into bid;
