  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://www.luxyhair.com/pages/ambassador-program-terms', 'https://www.luxyhair.com/pages/ambassador-program-terms', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Aspire', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.luxyhair.com/pages/ambassador-program-terms.', 'https://www.luxyhair.com/pages/ambassador-program-terms', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Luxy Hair Ambassador Program (Aspire)', 'https://www.luxyhair.com/pages/ambassador-program-terms', 'https://www.luxyhair.com/pages/ambassador-program-terms', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.luxyhair.com/pages/ambassador-program-terms', 'official_site', 'affiliate', 'Luxy Hair''s own Ambassador Program Terms publish the full structure: the ambassador network is provided by Aspire; ''All ambassadors will earn up to 10% commission'' when their code or link is used to redeem $20 USD off orders of $80 USD or more — base 5%, promoted to 7% after $5,000 USD in sales and 10% after $10,000 USD (with demotion after 6 months without converting); customers must purchase within 30 days of click-through; a PayPal address is required at registration; and the brand provides new extension sets twice a year. The terms publish NO statement about an earnings cap or maximum, so commission_cap is recorded as unknown, never guessed. The terms'' email addresses render masked in text form, so no email is recorded.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.luxyhair.com/pages/ambassador-program-terms', 'official_site', 'ugc_collab', 'The terms set explicit creator obligations: a minimum 3-month commitment, one piece of unique original content per month (Instagram post/reel/stories, YouTube review or tutorial, or TikTok post) tagging @luxyhair and #luxyhairpartner, following the brand on Instagram, TikTok and YouTube, and an exclusivity clause barring promotion of other hair-extension brands while enrolled.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.luxyhair.com/pages/ambassador-program-terms', 'official_site', 'creator_saturation', 'No Beacons brand page or other hard creator count for Luxy Hair surfaced in this research, so creator saturation is recorded as unknown rather than estimated.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 16, 11, 8, 6, 4, '{"niche_fit": "Extensions are a core hair-UGC category \u2014 transformations, tutorials and shade matching are proven formats.", "ugc_evidence": "A formal ambassador program with defined monthly content deliverables, tracked tags, and free product sets twice a year.", "compensation": "Tiered 5-10% is modest and commission only applies to $80+ orders using the $20-off code; no cap statement is published, so the cap stays honestly unknown. The recorded rate is the published top tier.", "contact_access": "Terms and application route on the brand''s own site (Aspire network); the terms'' email addresses render masked, so no public email is recorded.", "opportunity_availability": "Application-based, with a 3-month minimum commitment, monthly posting duty and a no-competing-extensions exclusivity clause.", "credibility": "Long-established extensions brand with fully published ambassador terms."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Lyssa Lashes', 'https://lyssalashes.com', 'False-eyelash brand running its affiliate program on GoAffPro: affiliates earn 10% commission on every referral order through their link or code, get 30% off personal purchases and a 10% follower discount code, are paid via PayPal on the first Monday of each month with no minimum payout threshold, and the brand''s own program page headlines the offer as ''Unlimited Earning Potential''.', null, 'published') returning id into bid;
