  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'GoAffPro', 10, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://lyssalashes.com/blogs/blog/lyssa-lashes-affiliate-program.', 'https://lyssalashes.com/blogs/blog/lyssa-lashes-affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Lyssa Lashes Affiliate Program (GoAffPro)', 'https://lyssalashes.com/blogs/blog/lyssa-lashes-affiliate-program', 'https://lyssalashes.com/blogs/blog/lyssa-lashes-affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://lyssalashes.com/blogs/blog/lyssa-lashes-affiliate-program', 'official_site', 'affiliate', 'Lyssa Lashes'' own affiliate program article (published 2024-10-28 on lyssalashes.com) details the GoAffPro-run program (signup portal at lyssalashes.goaffpro.com): 10% commission on every referral order, a 10% follower discount code, 30% off personal purchases, no strict posting requirements, and PayPal payments processed the first Monday of each month with no minimum payout threshold. Its benefits section is headed ''Unlimited Earning Potential'' and explains affiliates earn on all purchases made through their link — the earnings cap is therefore recorded as uncapped on the brand''s own explicit statement. Affiliate support is via the published info@lyssalashes.com.', 'verified', now());
