  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 12, 13, 12, 8, 3, '{"niche_fit": "Lashes are a staple makeup-UGC category (tutorials, try-ons, GRWM), though a single-category brand narrows content range.", "ugc_evidence": "A creator-welcoming program page aimed at enthusiasts, creators and makeup artists with dashboard tracking and promo tools; no hard creator count published.", "compensation": "10% on every referral order with the brand''s own page headlining ''Unlimited Earning Potential'' \u2014 verified uncapped at a standard lash rate.", "contact_access": "Published support email (info@lyssalashes.com) plus a live GoAffPro signup portal linked from the brand''s own article.", "opportunity_availability": "Open join \u2014 ''everyone is welcome'' \u2014 with no posting requirements after signup.", "credibility": "Small independent lash brand; program article dates from October 2024 and the portal is live."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('FullerSkin', 'https://fullerskin.hk', 'Hong Kong C60-fullerene skincare brand whose own Affiliate Agreement publishes a flat 20% commission on every referred sale, a 30-day referral cookie, monthly payouts in HKD to bank or PayPal in the first week of each month, a $500 minimum payout balance — and no maximum payout balance.', 'Hong Kong', 'published') returning id into bid;
