  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'FullerSkin Affiliate Program', 'https://fullerskin.hk/pages/affiliate-agreement', 'https://fullerskin.hk/pages/affiliate-agreement', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://fullerskin.hk/pages/affiliate-agreement', 'official_site', 'affiliate', 'FullerSkin''s own Affiliate Agreement (fullerskin.hk) publishes the full program terms: ''You''ll earn a sweet 20% commission when a customer purchases a FullerSkin product using your referral link'', a 30-day cookie, direct-link tracking from the affiliate''s own site, commissions paid in HKD to bank or PayPal in the first week of each month on commissions older than 30 days, and — in both the commissions section and the summary bullets — a minimum payout balance of $500 with ''no maximum payout balance'' / ''no maximum payout''. With no maximum on what the program pays out, the earnings cap is recorded as uncapped on the brand''s own explicit terms. Registrations are reviewed and moderated by the brand.', 'verified', now());
