  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 11, 17, 8, 7, 3, '{"niche_fit": "Single-ingredient-story (C60 fullerene) anti-aging skincare gives creators a clear review and routine angle.", "ugc_evidence": "A complete published affiliate agreement encouraging reviews and blog posts; no creator program extras or hard creator count published.", "compensation": "Flat 20% on every referred sale with ''no maximum payout'' stated twice in the brand''s own terms \u2014 verified uncapped at a high rate, tempered by the $500 payout threshold and HKD payment.", "contact_access": "Program terms and registration on the brand''s own site; no public affiliate email is published.", "opportunity_availability": "Applications are reviewed and moderated; dormant accounts are deactivated after 6 months without visits.", "credibility": "Small Hong Kong skincare label (Fullerskin HK Limited) with fully published program terms."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('MintPear', 'https://www.mintpear.com', 'Cruelty-free beauty brand (skincare and makeup) running a code-based Promoter program on its own site: promoters share a unique code giving followers free shipping on orders $45+ or 10% off the store, earn 15% of each sale made with their code in the first month and renew the code monthly to keep earning, are paid via PayPal or store credit, and the page states there are no limits to how much you can earn.', null, 'published') returning id into bid;
