  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'MintPear Promoter Program', 'https://www.mintpear.com/pages/become-a-promoter', 'https://www.mintpear.com/pages/become-a-promoter', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.mintpear.com/pages/become-a-promoter', 'official_site', 'affiliate', 'MintPear''s own Become A Promoter page publishes the program mechanics: apply with name and email, create your own promo code, and ''For the first month, every time someone uses your code to make a valid, processed, online payment, you''ll earn 15% of the sale. There are no limits to how much you can earn, so share away!'' — then renew the code each month to continue. The code gives followers free standard shipping on orders $45+ or 10% off the entire store, and payment is via PayPal (PayPal email required) or store credit. The earnings cap is therefore recorded as uncapped on the brand''s own explicit statement.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.mintpear.com/pages/become-a-promoter', 'official_site', 'creator_saturation', 'No Beacons brand page or other hard creator count for MintPear surfaced in this research, so creator saturation is recorded as unknown rather than estimated.', 'needs_review', now());
