  insert into public.brands (name, website, description, country, status) values ('BIOS Apothecary', 'https://www.biosapothecary.com', 'All-natural skincare and bath/body brand (BIOS Institute LLC) running its affiliate program on Affiliatly: affiliates earn 10% commission on new-customer purchases made within 30 days of the referral visit (or via their exclusive 10%-off coupon code), track everything in a private portal with creative assets, and are paid in USD via PayPal on the 1st of each month — with the brand''s terms stating there is no minimum or maximum payout amount.', null, 'published') returning id into bid;
