  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'BIOS Apothecary Affiliates Program (Affiliatly)', 'https://www.biosapothecary.com/pages/become-an-affiliate', 'https://www.biosapothecary.com/pages/become-an-affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.biosapothecary.com/pages/become-an-affiliate', 'official_site', 'affiliate', 'BIOS Apothecary''s own Affiliates Program page publishes the offer: 10% commission when a new customer buys via your referral link or 10%-off coupon code, applications reviewed within 24 hours, a private affiliate portal with real-time traffic/sales statistics and creative assets, and payouts ''in US dollars using Paypal on the 1st day of every month. There is no minimum or maximum payout amount.'' Signup runs through Affiliatly, linked from the brand''s page.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.biosapothecary.com/pages/affiliates-terms-and-conditions', 'official_site', 'affiliate', 'The brand''s own Affiliate Terms and Conditions repeat the economics in full: 10% commission on all sales generated within the first 30 days of the referral visit (each order in that window earns), the coupon ''can be used by an unlimited number of customers and never expires'', all products eligible, no application fees or minimum sales quotas, and in the Commissions section: ''There is no minimum or maximum payout amount.'' With the program''s own terms setting no maximum on payouts, the earnings cap is recorded as uncapped.', 'verified', now());
