  insert into public.brands (name, website, description, country, status) values ('Clear Skin Solutions', 'https://clearskinsolutions.com', 'Acne-focused med spa and skincare brand in Ardmore, Oklahoma, whose Affiliate Referral Program (announced on its own blog) pays a base 10% commission with bonus commissions for top performers, monthly PayPal payouts above a $150 threshold, and an FAQ stating there is no maximum cap on referral commission payouts — but the program''s linked application page returns 404 on a final re-check, so current enrollment is unconfirmed.', 'United States', 'published') returning id into bid;
