  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://clearskinsolutions.com/blogs/news/introducing-the-clear-skin-solutions-affiliate-referral-program', 'official_site', 'affiliate', 'Clear Skin Solutions'' own blog announcement of its Affiliate Referral Program answers the FAQ ''Is it really true that there is no maximum cap on referral commission payouts?'' with ''That''s right: with a base commission of 10%, we put no cap on your earning potential as a CSS Affiliate'' plus individual bonus commissions for top performers, a $150 minimum payment threshold, and automated payouts within the first week of each month via PayPal. No prerequisites beyond an application form and approval. The cap is recorded as uncapped on the brand''s own explicit statement, but the announcement dates from December 2020, so this evidence is marked needs_review.', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://clearskinsolutions.com/blogs/news/introducing-the-clear-skin-solutions-affiliate-referral-program', 'official_site', 'affiliate', 'FINAL RE-CHECK FLAG: the program page the announcement links to (clearskinsolutions.com/affiliate-program/) returned HTTP 404 when re-checked on 2026-11-20, so the program''s current enrollment route could not be confirmed even though the announcement and its no-cap FAQ remain live on the brand''s site. The brand''s published contact on the same page is info@clearskinsolutions.com (808 16th Ave NW, Ardmore, OK). Treat enrollment as unconfirmed until the brand responds.', 'needs_review', now());
