  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.amavii.com/pages/affiliate-faq', 'official_program_page', 'affiliate_program', 'Earnings answered explicitly in the official FAQ: ''How much can I earn? That''s completely up to you. There is no cap on your commission earnings... Our standard commission rate is 12%-20% for every sale you make.'' The recorded rate is the 12% floor of that published standard range.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 12, 16, 12, 8, 3, '{"niche_fit": "Sunglasses and frames are an easy try-on and styling fit for fashion and lifestyle creators.", "ugc_evidence": "The FAQ encourages product reviews and video creatives, but the programme is a classic network affiliate setup with no published creator counts.", "compensation": "Standard rate published as a 12%-20% range with an explicit ''no cap on your commission earnings'' statement; the floor of the range is recorded.", "contact_access": "Published affiliate email (affiliates@amavii.com) with a stated 24-hour reply time.", "opportunity_availability": "Open via ShareASale sign-up with manual review inside 2 business days; most countries eligible.", "credibility": "Small eyewear brand running a standard network programme; mid-low credibility."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Yoga Design Lab', 'https://yogadesignlab.com', 'Design-led yoga brand (Yoga Design Lab, Inc.) selling printed yoga mats, towels and accessories. Its affiliate programme runs on GoAffPro with structured creator expectations (monthly posts and regular video content), and its official programme terms state there is no ceiling on commissions; the terms do not publish a commission rate.', null, 'published') returning id into bid;
