  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://yogadesignlab.com/en-in/pages/yoga-design-lab-affiliate-program-terms-conditions', 'official_program_page', 'affiliate_program', 'Official affiliate programme terms: tracking and commission records run through the GoAffPro platform with a 30-day cookie; payments via PayPal after a 30-day hold, with a $50 minimum threshold.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://yogadesignlab.com/en-in/pages/yoga-design-lab-affiliate-program-terms-conditions', 'official_program_page', 'affiliate_program', 'Commission cap stated explicitly in the official terms, Commissions section: ''Yoga Design Lab can adjust commission rates at its discretion. There is no ceiling on commissions.'' No commission percentage is published anywhere in the terms, so the rate is recorded as null.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://yogadesignlab.com/en-in/pages/yoga-design-lab-affiliate-program-terms-conditions', 'official_program_page', 'creator_program', 'The programme is creator-structured: affiliates must be 18+, run an engaged social audience relevant to the brand, post at least one unique post per month and create reel/story/video content bi-monthly, with quarterly performance reviews; affiliate@yogadesignlab.com is named as the primary contact.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 15, 11, 13, 6, 4, '{"niche_fit": "Visually distinctive yoga mats and gear are a natural fit for yoga and fitness creators'' practice content.", "ugc_evidence": "The terms build in monthly posts and bi-monthly video content with engagement expectations, showing an active creator programme, though no creator counts are published.", "compensation": "No ceiling on commissions is stated in the official terms, but no rate is published there either, so compensation scores mid-range.", "contact_access": "A dedicated affiliate email (affiliate@yogadesignlab.com) is named in the terms as the primary contact channel.", "opportunity_availability": "Application-based with eligibility conditions, content expectations and quarterly reviews, so availability is more selective than an open programme.", "credibility": "Established, internationally sold yoga brand with formal published programme terms."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Cate & Chloe', 'https://www.cateandchloe.com', 'Women''s jewellery brand selling necklaces, earrings and bracelets (average order size $99, ships to the US and Canada). Its affiliate programme runs on Awin with a dedicated affiliate manager, and its official FAQ states there are no limits on the amount of commission an affiliate can earn; the page''s own rate figures conflict, so no single rate is recorded.', null, 'published') returning id into bid;
