  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', null, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://gma.cateandchloe.com/pages/affiliates.', 'https://gma.cateandchloe.com/pages/affiliates', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Cate & Chloe Affiliate Program (Awin)', 'https://gma.cateandchloe.com/pages/affiliates', 'https://gma.cateandchloe.com/pages/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://gma.cateandchloe.com/pages/affiliates', 'official_program_page', 'affiliate_program', 'Official affiliates page: the programme runs through Awin (the page links to the Awin express sign-up), with a 45-day cookie, a product datafeed, monthly Awin payments, and a dedicated affiliate manager contactable at affiliates@cateandchloe.com.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://gma.cateandchloe.com/pages/affiliates', 'official_program_page', 'affiliate_program', 'Earnings cap answered explicitly in the official FAQ: ''there are no limitations or restrictions on what Cate & Chloe products can be sold through our affiliate program, AND there are no limits on the amount of commission you can earn as an affiliate.''', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://gma.cateandchloe.com/pages/affiliates', 'official_program_page', 'affiliate_program', 'RATE CONFLICT on the brand''s own page: the highlights state ''10% commission on all sales'', the FAQ body states the Awin account ''is credited 15% of the entire order'', and the commission-levels answer states ''a commission up to 20% with increased commissions offered for exceptional performance''. The figures cannot be reconciled from the page, so commission_rate is recorded as null.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 10, 13, 8, 4, '{"niche_fit": "Affordable women''s jewellery with a $99 average order is a strong unboxing and styling fit for fashion creators.", "ugc_evidence": "Awin programme with a datafeed and creative assets for publishers; no creator counts published.", "compensation": "No limit on commission earnings is stated explicitly, but the page conflicts on the rate itself (10% vs 15% vs up to 20%), so compensation scores low until the rate is settled inside Awin.", "contact_access": "A dedicated affiliate manager with a published email (affiliates@cateandchloe.com).", "opportunity_availability": "Open to any family-friendly website via Awin sign-up; shipping limited to the US and Canada.", "credibility": "Established jewellery brand running on a major network with a named programme manager."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Lifespan Fitness', 'https://www.lifespanfitness.com.au', 'Australian fitness equipment retailer selling treadmills, bikes, gym gear and rehabilitation supports. Its affiliate programme is open to fitness professionals, influencers, bloggers and online coaches, offers a dedicated affiliate manager, and its official FAQ states there is no cap on earnings; the commission breakdown is only given after acceptance, so no rate is recorded.', 'Australia', 'published') returning id into bid;
