  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', null, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://www.lifespanfitness.com.au/pages/affiliate.', 'https://www.lifespanfitness.com.au/pages/affiliate', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Lifespan Fitness Affiliate Program', 'https://www.lifespanfitness.com.au/pages/affiliate', 'https://www.lifespanfitness.com.au/pages/affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.lifespanfitness.com.au/pages/affiliate', 'official_program_page', 'affiliate_program', 'Official affiliate page: apply on the page, acceptance review by the team, then an account on the brand''s affiliate platform with customised linking tools; commissions on all orders at lifespanfitness.com.au, paid to a nominated bank account about 45-60 days after month end, with no minimum payout threshold and a dedicated affiliate manager.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.lifespanfitness.com.au/pages/affiliate', 'official_program_page', 'affiliate_program', 'Earnings cap answered explicitly in the official FAQ: ''How much can I earn as a Lifespan Fitness affiliate? There is no cap on earnings.'' The page does not publish a commission percentage (the breakdown is provided on acceptance), so commission_rate is recorded as null.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.lifespanfitness.com.au/pages/affiliate', 'official_program_page', 'creator_program', 'The programme explicitly recruits health service providers, fitness professionals, bloggers, social media influencers and online coaches, and joining is free.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 14, 12, 6, 7, 4, '{"niche_fit": "A full range of home fitness and rehab equipment gives fitness creators broad, high-ticket products to demonstrate.", "ugc_evidence": "The page explicitly recruits influencers, bloggers and online coaches and offers a dedicated manager, but publishes no creator counts.", "compensation": "No cap on earnings is stated in the FAQ and higher tiers unlock with performance, but the actual rate is unpublished until acceptance, so compensation stays mid-range.", "contact_access": "No affiliate email is published on the page; contact is the on-page application form or the retail phone line (1300 169 600).", "opportunity_availability": "Application with a team review before acceptance; free to join with no payout threshold.", "credibility": "Established Australian fitness retailer with a physical support line and detailed published FAQ."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Zizuka', 'https://zizuka.in', 'Indian baby-clothing brand selling 100% natural muslin and cotton baby essentials. Its own affiliate programme recruits parent creators, mom bloggers and YouTubers, pays monthly to bank/UPI with a 30-day cookie, and its FAQ states there is no cap on earnings; the page conflicts on the rate (3% vs 10%), so no single rate is recorded.', 'India', 'published') returning id into bid;
