  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Zizuka Affiliate Program', 'https://zizuka.in/pages/affiliate', 'https://zizuka.in/pages/affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://zizuka.in/pages/affiliate', 'official_program_page', 'affiliate_program', 'Official affiliate page: open application on the page (reviewed within 2-3 business days), unique tracking link and real-time dashboard, ready-to-use product images and banners, affiliate-only discount codes, 30-day cookie, monthly payouts to bank account or UPI on confirmed, non-returned orders.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://zizuka.in/pages/affiliate', 'official_program_page', 'affiliate_program', 'Earnings cap answered explicitly in the official FAQ: ''How much can I earn? There is no cap on your earnings. The more your audience shops, the more you earn.''', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://zizuka.in/pages/affiliate', 'official_program_page', 'affiliate_program', 'RATE CONFLICT on the brand''s own page: the ''What You Earn'' section states ''3% commission on every confirmed sale'' and the FAQ example pays Rs 30 on a Rs 1,000 order (3%), but Step 4 of ''How It Works'' states ''you earn 10% of the order value''. The figures conflict, so commission_rate is recorded as null.', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://zizuka.in/pages/affiliate', 'official_program_page', 'creator_program', 'The programme is aimed at mom bloggers, parenting Instagram creators and YouTubers, explicitly welcomes small followings (''a parent with 2,000 highly engaged followers... is far more valuable than an account with 100,000 passive followers''), and states ''hundreds of creators and parents'' already earn with it - a few hundred is mid-size, so saturation is recorded as unknown, not low.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 20, 14, 9, 11, 9, 2, '{"niche_fit": "Muslin baby essentials fit parenting and family creators rather than general fashion creators, so niche fit is narrower.", "ugc_evidence": "The page is written directly for parent creators and small engaged followings, with content ideas and creative assets provided.", "compensation": "No cap on earnings is stated, but the page''s own rate figures conflict (3% vs 10%) and even the higher figure is modest, so compensation scores low.", "contact_access": "Published contact email (customercare@zizuka.in) and phone number on the affiliate page.", "opportunity_availability": "Open application on the brand''s own page; small followings explicitly welcome.", "credibility": "Small young Indian DTC brand, so credibility stays low."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Pravacana Mats', 'https://www.pravacanamats.com', 'US yoga-mat brand (Raleigh, NC) selling artist-designed, eco-focused yoga mats. It runs both an affiliate programme (commissions start at 5% and can range up to 25% during promotions or on performance) and an exclusive ambassador programme, and its FAQ states there is no limit or cap to monthly commissions.', 'United States', 'published') returning id into bid;
