  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 5, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://www.pravacanamats.com/affiliates-ambassadors.', 'https://www.pravacanamats.com/affiliates-ambassadors', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Pravacana Mats Affiliate & Ambassador Program', 'https://www.pravacanamats.com/affiliates-ambassadors', 'https://www.pravacanamats.com/affiliates-ambassadors', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.pravacanamats.com/affiliates-ambassadors', 'official_program_page', 'affiliate_program', 'Official affiliates page: affiliates earn commission via a custom link or code on tracked purchases, paid monthly on the 7th via PayPal, Stripe or cheque; ''Affiliate commissions levels start at 5% and can range up to 25% during specific promotions or based on performance.'' The recorded rate is the 5% starting level.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.pravacanamats.com/affiliates-ambassadors', 'official_program_page', 'affiliate_program', 'Commission cap answered explicitly in the official FAQ: ''What is the cost to join either program? There is absolutely no cost to you... There is no limit or cap to monthly commissions, nor is any amount deducted from your commissions (except refunds), ever.''', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.pravacanamats.com/affiliates-ambassadors', 'official_program_page', 'creator_program', 'Alongside the open affiliate tier, an Ambassador tier offers co-branded promotions and exclusive commission levels for partners with an existing fan base or following of at least 3,000+; promotion via social media, blogs and websites is spelled out on the page. No contact email is published on the page.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 14, 13, 5, 8, 3, '{"niche_fit": "Artist-designed yoga mats are a natural visual fit for yoga creators'' practice and studio content.", "ugc_evidence": "Two creator tiers (affiliate plus ambassador with co-branded promotions) and named promotion channels, but no creator counts published.", "compensation": "Starting rate is a modest 5%, rising to 25% only in promotions or on performance, with an explicit no-limit-or-cap statement on monthly commissions.", "contact_access": "No email is published on the programme page; contact is via the on-site application links (a Raleigh, NC postal address is shown).", "opportunity_availability": "Affiliate tier is open to apply; the ambassador tier requires an existing following of at least 3,000.", "credibility": "Small US niche brand with a published postal address and detailed programme FAQ."}'::jsonb);
