  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.affiliatly.com/af-1015385/affiliate.panel', 'official_site', 'affiliate', 'Sunwarrior''s own affiliate panel on Affiliatly states verbatim: ''the earnings are uncapped'' and ''You can make as much as you want - it is in your hands.'' The panel sets a $100 payout threshold, pays on the 2nd Thursday of each month, and publishes affiliates@sunwarrior.com for contact. The cap is verified uncapped on the brand''s own affiliate portal.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/sunwarrior/', 'creator_directory', 'affiliate', 'Third-party listings conflict on Sunwarrior''s creator commission rate: the Impact listing is reported at 5%, a Shopper listing at 6%, and the brand''s separate salon partnership page offers stylists 10% plus a 10% client discount. No single creator rate settles across fetched sources, so commission_rate is recorded as null rather than guessed.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.affiliatly.com/af-1015385/affiliate.panel', 'official_site', 'contact', 'The brand''s affiliate panel publishes affiliates@sunwarrior.com as the affiliate contact and describes dashboard tracking of visitors, leads and sales.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 15, 14, 13, 8, 5, '{"compensation": "Earnings are verified uncapped, but the creator commission rate conflicts across sources (5% Impact listing, 6% Shopper, 10% salon partnership), so the rate is null and the score is held down.", "contact_access": "A dedicated affiliates@sunwarrior.com contact is published on the brand''s own affiliate panel.", "credibility": "An established plant-based nutrition brand founded in 2008 with wide retail and online distribution.", "niche_fit": "Plant-based protein and superfoods are a core UGC category for fitness and wellness creators.", "opportunity_availability": "The affiliate panel is open for sign-up with published payout terms.", "ugc_evidence": "A public affiliate panel plus a separate creator content program on the brand''s site; no creator counts were published on fetched pages."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Peremis', 'https://peremis.com', 'Direct-to-consumer supplement brand selling third-party tested, US-made wellness supplements through a tiered brand-direct partner program built for creators on TikTok, Instagram and YouTube.', null, 'published') returning id into bid;
