  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Peremis Partner Program', 'https://peremis.com/pages/partners', 'https://peremis.com/pages/partners', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://peremis.com/pages/partners', 'official_site', 'affiliate', 'Peremis''s official partners page states verbatim: ''Earn 20% to 35% on every sale you drive. No caps. No fees.'' Tiers run Bronze 20% (everyone starts here), Silver 25% at 200 sales/month, Gold 30% at 500 and Ambassador 35% at 1,000, plus monthly bonuses and a 2-5% partner-referral share for 12 months. Commissions clear after 30 days and pay out over $50 via PayPal or store credit. The page explicitly notes TikTok Shop checkouts cannot be credited, so the program is brand-direct. The cap is verified uncapped on the brand''s own page.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://peremis.com/pages/partners', 'official_site', 'general', 'The same page says there is no minimum audience and no application fee, supplies partners with content kits and creative assets, and describes products as third-party tested and made in the USA in cGMP facilities.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 16, 19, 8, 9, 3, '{"compensation": "20% starting commission rising to 35% by tier, with an explicit ''No caps'' statement on the brand''s own page.", "contact_access": "No partner email is published; contact runs through the partner dashboard and application form only.", "credibility": "A young, small brand with a thin public footprint; third-party testing and cGMP claims are stated on its own page only.", "niche_fit": "Supplements pitched directly at short-form wellness creators on TikTok, Instagram and YouTube.", "opportunity_availability": "Open enrollment with no minimum audience and no application fee.", "ugc_evidence": "The partners page is written for content creators and supplies content kits and creative assets; no creator counts were published."}'::jsonb);
