  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Methyl-Life Affiliate Program (UpPromote)', 'https://methyl-life.com/pages/health-fitness-supplements-affiliate-program', 'https://methyl-life.com/pages/health-fitness-supplements-affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://methyl-life.com/pages/health-fitness-supplements-affiliate-program', 'official_site', 'affiliate', 'Methyl-Life''s official affiliate page publishes an 8% commission and states verbatim in its FAQ: ''There are no limits to how much you can make as a Methyl-Life affiliate.'' A second section is headed ''Unlimited Earning Potential'' and says there are ''no upper limits to the commissions you can earn.'' The program is in-house via UpPromote, with a 30-day cookie, a $50 minimum payout threshold, a 60-day payment term and custom discount codes for followers. The cap is verified uncapped on the brand''s own page.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://methyl-life.com/pages/health-fitness-supplements-affiliate-program', 'official_site', 'contact', 'The same page publishes support@methyl-life.com for affiliate questions and a Shoreline, Washington address, and states that top affiliates may be featured on the brand''s website and social channels.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 14, 15, 12, 8, 4, '{"compensation": "8% is a modest rate, but earnings are explicitly uncapped in the program FAQ on the brand''s own page.", "contact_access": "A published support email covers affiliate questions, alongside a full public FAQ.", "credibility": "A founder-led specialist brand with a physical US address published on the program page.", "niche_fit": "MTHFR and methylation content is a deep, underserved health niche with a loyal creator community.", "opportunity_availability": "Open application through the brand''s page with published cookie, threshold and payment terms.", "ugc_evidence": "The program explicitly recruits health practitioners, bloggers and content creators and offers featured placement for top affiliates."}'::jsonb);
