  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Mountain Rose Herbs Affiliate Program', 'https://mountainroseherbs.com/affiliates/', 'https://mountainroseherbs.com/affiliates/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://mountainroseherbs.com/affiliates/', 'official_site', 'affiliate', 'Mountain Rose Herbs'' official affiliate page publishes a 10% commission on referral revenue, paid monthly once commissions reach $50, with payments processed through the AspireIQ platform per the program contract linked from the page. Requirements include 1,000+ cumulative followers or an established website, and affiliates must generate at least 12 sales and 120 clicks per year to stay active. No earnings-cap statement appears on the page, so the cap is recorded as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://mountainroseherbs.com/affiliates/', 'official_site', 'contact', 'The same page publishes affiliate@mountainroseherbs.com for program questions and describes the brand as a supplier of organic and sustainable botanical products since 1987.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 12, 13, 7, 5, '{"compensation": "10% commission is mid-range and no cap statement is published, so the cap stays unknown.", "contact_access": "A dedicated affiliate@mountainroseherbs.com contact is published on the program page.", "credibility": "Operating since 1987 with a long-standing reputation in the herbal products market.", "niche_fit": "Herbs, teas and DIY botanical content map directly onto herbalism, recipe and natural-living creators.", "opportunity_availability": "Open application, but a 1,000-follower minimum and yearly activity minimums narrow access.", "ugc_evidence": "The program page explicitly recruits bloggers, recipe creators and photographers; no creator counts were published."}'::jsonb);
