  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.mylifeinfused.com/affiliate-program/', 'official_site', 'affiliate', 'Life Infused''s official affiliate page publishes a 15% commission and states verbatim: ''Monthly payouts and unlimited earnings potential.'' Terms include a 90-day cookie, a $50 minimum payout threshold and monthly PayPal payments. The program prefers partners with 2,000+ followers and requires affiliates to stay active with regular promotion. The cap is recorded uncapped on the page''s explicit unlimited-earnings statement; the page copy is older, so terms should be re-confirmed at sign-up.', 'verified', now());
