  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Banyan Tree Collective Affiliate Partnership (AvantLink)', 'https://www.banyanbotanicals.com/pages/customer-service-partner-with-us', 'https://www.banyanbotanicals.com/pages/customer-service-partner-with-us', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.banyanbotanicals.com/pages/customer-service-partner-with-us', 'official_site', 'affiliate', 'Banyan Botanicals'' official Partner with Us page describes the Banyan Tree Collective: affiliate partners receive a 15% discount to share with their community plus a 15% commission for recommending Banyan products, with applications completed through AvantLink per the brand''s wholesale affiliates page. The program targets wellness professionals and individuals with a dedicated social following. No earnings-cap statement is published, so the cap is recorded as unknown. (An older 2020 third-party review cites 20% and a 365-day cookie; the brand''s own current pages say 15%, which is what is recorded.)', 'verified', now());
