  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://vedawarrior.com/pages/affiliates', 'official_site', 'affiliate', 'Veda Warrior''s official affiliates page states verbatim: ''Earn unlimited commissions promoting products you believe in'' and its FAQ answers ''Is there a limit to how much I can earn?'' with ''There''s no limit to how much you can earn. Your earning potential is based on your performance and audience engagement.'' The page publishes sub-affiliate tiers (5% first level, 3% second, 1% third) and a 30-day cookie, tracked through a GrowthHero dashboard, but does not publish the base commission rate, so commission_rate is null. The cap is verified uncapped on the brand''s own page.', 'verified', now());
