  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.mysilvery.com/pages/affiliate-q-a', 'official_site', 'affiliate', 'Official Silvery affiliate FAQ fetched: tiered commission — Tier 1 (0-25 referrals) 10%, Tier 2 (26-75) 15%, Tier 3 (76+) 20% — on all products, 30-day attribution window, monthly payouts via Tremendous with a $50 minimum. The FAQ answers ''Is there a limit to how much I can earn?'' with ''No. There is no cap on earnings.'' — an explicit no-cap statement on the brand''s own page, so the commission cap is recorded as UNCAPPED. The recorded 20% is the published top-tier ceiling. Applications run through a form hosted on Social Snowball.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.mysilvery.com/pages/affiliate-q-a', 'official_site', 'ugc_collab', 'The same FAQ says the program is open to creators, influencers, bloggers and content publishers, encourages authentic original content on social media, blogs, newsletters and video platforms, grants a free set of Silvery Restcool Silver-Infused Bed Sheets on joining, and notes top-performing affiliates may be invited to paid collaborations, ambassador programs or early product launches. Support is via the site''s email/call options (Mon-Fri 9am-5pm EST, phone +1 762-920-1623); no program email address is published in the page text.', 'verified', now());
