  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://olloaudio.com/pages/affiliate', 'official_site', 'affiliate', 'Official OLLO Audio affiliate page fetched: partners earn 20% commission on every sale made through their unique affiliate link or code with 100% attribution, their audience receives 10% off, and partners get creator benefits, complimentary products, early product access and priority support. Payments are made against official invoices following monthly sales reports, so partners must have a registered company or sole-trader status. No ''no cap'' / ''unlimited'' / earnings-limit statement appears on the fetched page, so the commission cap is honestly recorded as UNKNOWN.', 'verified', now());
