  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://uppromote.com/affiliate-programs/cat/', 'listing', 'affiliate', 'Affiliate-program listings consistently report the Hepper program at a 12% starting commission (higher for proven partners), 30-day cookie, $50 payment threshold and payouts via AffiliateWP by bank transfer, with applications reviewed within about 48 hours and 1:1 support from an in-house affiliate team; average order value is reported at $60+. The brand''s own program URL (hepper.com/join-hepper-cat-affiliate-program/) redirected to the shop page when fetched this round, and the ''no limit to how much you can earn'' wording appears only in third-party blog write-ups, not on a fetched Hepper page — so the commission cap is honestly recorded as UNKNOWN rather than uncapped.', 'publicly_reported', now());
